let attackPlannerData=null,attackPlannerMine=false,attackPlannerBusy=false;
function attackPlannerBookingHTML(op,t,b){
 const d=attackPlannerData,owner=b.ownerId===d.userId,participant=owner||b.users.includes(d.userId),released=['Open','Prereleased'].includes(op.phase),attrs=' data-operation="'+esc(op.id)+'" data-booking="'+esc(b.id)+'"',button=(action,label)=>'<button class="btn" data-operation-action="'+action+'"'+attrs+'>'+label+'</button>';
 if(!b.ownerId)return '<div class="attack-wave"><b>LT '+b.landTick+'</b><small>Available</small>'+((released&&d.canClaim)?button('claim','BOOK WAVE'):'')+'</div>';
 return '<div class="attack-wave"><b>LT '+b.landTick+' · '+esc(b.status)+'</b><small>'+esc(b.ownerName)+(b.users.length?' + '+b.users.length+' shared':'')+'</small>'+(participant&&released?'<details class="attack-booking-editor" data-booking-editor="'+esc(b.id)+'"><summary>MY BOOKING · EDIT</summary><label>Status<select data-booking-field="status">'+['none','land','recall'].map(s=>'<option '+(b.status===s?'selected':'')+'>'+s+'</option>').join('')+'</select></label><label>Battle group<input maxlength="80" data-booking-field="group" value="'+esc(b.group)+'"></label><label>Notes<textarea maxlength="2000" data-booking-field="notes">'+esc(b.notes)+'</textarea></label><label>Battle calculator reference<input maxlength="2000" data-booking-field="battleCalc" value="'+esc(b.battleCalc)+'"></label>'+button('booking','SAVE BOOKING')+(owner?'<label>Shared alliance members<select multiple data-booking-field="users" aria-label="Shared users for LT '+b.landTick+'">'+d.members.filter(m=>m.id!==d.userId).map(m=>'<option value="'+esc(m.id)+'" '+(b.users.includes(m.id)?'selected':'')+'>'+esc(m.username)+'</option>').join('')+'</select></label>'+button('share','SAVE SHARED USERS')+'<label>Transfer owner<select data-booking-field="owner"><option value="">Choose another member</option>'+d.members.filter(m=>m.id!==d.userId).map(m=>'<option value="'+esc(m.id)+'">'+esc(m.username)+'</option>').join('')+'</select></label>'+button('transfer','TRANSFER OWNERSHIP'):'')+button('drop',owner?'DROP BOOKING':'LEAVE SHARED BOOKING')+'</details>':(b.notes?'<p>'+esc(b.notes)+'</p>':''))+'</div>';
}
function attackPlannerHTML(){const d=attackPlannerData;
 const form=d.canManage?'<details class="panel attack-new-operation"><summary>CREATE ATTACK OPERATION</summary><form id="attackOperationForm" class="attack-operation-form"><label>Title<input name="title" maxlength="80" required></label><label>First land tick<input name="landTick" type="number" min="1" max="1000000" value="'+(state.tick+6)+'" required></label><label>Waves<select name="waves">'+Array.from({length:10},(_,i)=>'<option>'+ (i+1)+'</option>').join('')+'</select></label><label>Scheduled opening · optional<input name="releaseAt" type="datetime-local"></label><label>Prerelease · optional<input name="prereleaseAt" type="datetime-local"></label><label class="attack-wide">Target coordinates · one per line<textarea name="targets" rows="4" placeholder="1:2:3&#10;1:2:4" required></textarea></label><label class="attack-wide">Operation notes<textarea name="notes" maxlength="4000" rows="3"></textarea></label><button class="btn primary">CREATE OPERATION</button></form></details>':'';
 const cards=d.operations.map(op=>{const bookings=op.targets.flatMap(t=>t.bookings),claimed=bookings.filter(b=>b.ownerId).length,targets=op.targets.filter(t=>!attackPlannerMine||t.bookings.some(b=>b.ownerId===d.userId||b.users.includes(d.userId))),button=(a,label)=>'<button class="btn" data-operation-action="'+a+'" data-operation="'+esc(op.id)+'">'+label+'</button>';
 return '<section class="panel attack-operation"><div class="ph"><div><b>'+esc(op.title)+'</b><small>LT '+op.landTick+' · '+op.waves+' waves · '+claimed+'/'+bookings.length+' booked</small></div><span class="tag">'+esc(op.phase)+'</span></div><div class="attack-operation-body">'+(op.notes?'<p>'+esc(op.notes)+'</p>':'')+(op.legacy?'<p class="note">Imported from the previous target board; existing claim retained.</p>':'')+(op.releaseAt?'<p>Opening: '+esc(new Date(op.releaseAt).toLocaleString())+(op.prereleaseAt?' · Prerelease: '+esc(new Date(op.prereleaseAt).toLocaleString()):'')+'</p>':'')+(d.canManage?'<div class="controls">'+(op.phase==='Closed'?button('reopen','REOPEN'):button('close','CLOSE')+(op.phase!=='Open'?button('release','OPEN NOW'):'')+(op.waves<10?button('wave','ADD WAVE'):'')+(op.waves>1?button('removeWave','REMOVE LAST WAVE'):''))+'</div>':'')+(d.canManage&&op.phase!=='Closed'?attackOperationEditorHTML(op):'')+targets.map(t=>'<article class="attack-target-waves"><h4>'+esc(displayCoords(t.coords))+'</h4>'+(d.canManage&&op.phase!=='Closed'?'<button class="btn" data-operation-action="removeTarget" data-operation="'+esc(op.id)+'" data-target="'+esc(t.id)+'">REMOVE TARGET</button>':'')+'<div class="attack-wave-grid">'+t.bookings.filter(b=>!attackPlannerMine||b.ownerId===d.userId||b.users.includes(d.userId)).map(b=>attackPlannerBookingHTML(op,t,b)).join('')+'</div></article>').join('')+(!targets.length?'<p>'+ (op.phase==='Scheduled'&&!d.canManage?'Targets will be visible at prerelease or opening.':attackPlannerMine?'No bookings for you in this operation.':'No targets.')+'</p>':'')+'</div></section>';
 }).join('');
 return '<section class="attack-planner-intro"><h3>Alliance attack planner</h3><p>Adapted from <a href="https://bitbucket.org/liamrigg/pa-tools" target="_blank" rel="noopener">pa-tools</a>: operations, consecutive land ticks and shared wave bookings. Booking status is planning information; launch actual fleets from Fleets or Alliance Launch Bay.</p><div class="controls"><label><input type="checkbox" id="attackMine" '+(attackPlannerMine?'checked':'')+'> My bookings only</label><button class="btn" data-operation-refresh>REFRESH PLANNER</button></div><p id="attackPlannerStatus" role="status"></p></section>'+form+cards+(d.operations.length?'':'<p>No attack operations in this round.</p>');
}
async function loadAllianceAttackBoard(){const box=document.getElementById('allianceAttackBoard');if(!box)return;try{const data=await centralDirectoryRequest('/api/alliance-operations');if(allianceTab!=='attack'||!box.isConnected)return;attackPlannerData=data;box.innerHTML=attackPlannerHTML();}catch(e){box.textContent=e.message;}}
document.addEventListener('submit',async e=>{if(e.target.id!=='attackOperationForm')return;e.preventDefault();if(attackPlannerBusy)return;attackPlannerBusy=true;const f=new FormData(e.target),date=key=>f.get(key)?new Date(f.get(key)).getTime():null;try{const targets=String(f.get('targets')).split(/[\s,;]+/).filter(Boolean).map(c=>c.split(':').map(n=>String(Number(n)).padStart(2,'0')).join(':'));await centralDirectoryRequest('/api/alliance-operations',{action:'create',generation:attackPlannerData.generation,title:f.get('title'),landTick:Number(f.get('landTick')),waves:Number(f.get('waves')),targets,notes:f.get('notes'),releaseAt:date('releaseAt'),prereleaseAt:date('prereleaseAt')});await loadAllianceAttackBoard();notify('Attack operation created.');}catch(error){document.getElementById('attackPlannerStatus').textContent=error.message;}finally{attackPlannerBusy=false;}});
document.addEventListener('change',e=>{if(e.target.id==='attackMine'){attackPlannerMine=e.target.checked;document.getElementById('allianceAttackBoard').innerHTML=attackPlannerHTML();}});
document.addEventListener('click',async e=>{if(e.target.closest('[data-operation-refresh]')){await loadAllianceAttackBoard();return;}const b=e.target.closest('[data-operation-action]');if(!b||attackPlannerBusy)return;const op=attackPlannerData.operations.find(o=>o.id===b.dataset.operation);if(!op)return;const body={action:b.dataset.operationAction,id:op.id,revision:op.revision,generation:attackPlannerData.generation,bookingId:b.dataset.booking,targetId:b.dataset.target},editor=b.closest('[data-booking-editor]'),field=k=>editor?.querySelector('[data-booking-field="'+k+'"]');if(body.action==='edit'){const edit=b.closest('[data-operation-editor]');body.title=edit.querySelector('[data-operation-field=title]').value;body.notes=edit.querySelector('[data-operation-field=notes]').value;body.landTick=Number(edit.querySelector('[data-operation-field=landTick]').value);}if(body.action==='targets'){const edit=b.closest('[data-operation-editor]');body.targets=edit.querySelector('[data-operation-field=targets]').value.split(/[\s,;]+/).filter(Boolean).map(c=>c.split(':').map(n=>String(Number(n)).padStart(2,'0')).join(':'));}if(body.action==='booking')for(const k of ['status','group','notes','battleCalc'])body[k]=field(k).value;if(body.action==='share')body.users=[...field('users').selectedOptions].map(o=>o.value);if(body.action==='transfer')body.userId=field('owner').value;attackPlannerBusy=true;b.disabled=true;try{await centralDirectoryRequest('/api/alliance-operations',body);await loadAllianceAttackBoard();notify('Attack planner saved.');}catch(error){const status=document.getElementById('attackPlannerStatus');if(status)status.textContent=error.message;b.disabled=false;}finally{attackPlannerBusy=false;}});

function attackOperationEditorHTML(op){return '<details class="attack-operation-editor" data-operation-editor="'+esc(op.id)+'"><summary>MANAGE OPERATION</summary><div class="attack-operation-form"><label>Title<input data-operation-field="title" maxlength="80" value="'+esc(op.title)+'"></label><label>First land tick<input type="number" min="1" max="1000000" data-operation-field="landTick" value="'+op.landTick+'"></label><label class="attack-wide">Notes<textarea maxlength="4000" data-operation-field="notes">'+esc(op.notes)+'</textarea></label><button class="btn" data-operation-action="edit" data-operation="'+esc(op.id)+'">SAVE OPERATION</button><label class="attack-wide">Add target coordinates<textarea data-operation-field="targets" rows="3"></textarea></label><button class="btn" data-operation-action="targets" data-operation="'+esc(op.id)+'">ADD TARGETS</button></div></details>';}
